101	    async createWorkspace(projectId: string, workspaceId: string): Promise<OrchestrationResult> {
102	        const project = this.projectManager.getById(projectId);
103	        if (!project) {
104	            throw new Error(
105	                `Cannot create workspace: project with ID "${projectId}" does not exist.`
106	            );
107	        }
108	
109	        const wsFolder = this.workspaceFolder(projectId, workspaceId);
110	        fs.mkdirSync(wsFolder, { recursive: true });
111	
112	        const resolvedProjectsFolder = path.resolve(this.config.projectsFolder);
113	
114	        const repoResults: OrchestrationRepoResult[] = await Promise.all(
115	            project.Repositories.map(async (repoId): Promise<OrchestrationRepoResult> => {
116	                const repo = this.repositoryManager.getById(repoId);
117	                if (!repo) {
118	                    return {
119	                        repositoryId: repoId,
120	                        success: false,
121	                        error: `Repository with ID "${repoId}" does not exist in the repository store.`,
122	                    };
123	                }
124	
125	                const destination = this.repoPath(projectId, workspaceId, repoId);
126	
127	                // Skip repos that are already cloned on disk (idempotent retry).
128	                // Check for `.git` rather than just the directory: a failed clone
129	                // may leave behind an empty or partial directory that is not a
130	                // usable repository.
131	                if (fs.existsSync(path.join(destination, '.git'))) {
132	                    return { repositoryId: repoId, success: true };
133	                }
134	
135	                // Remove leftover directory from a previously failed clone so
136	                // that `git clone` can create it cleanly.
137	                if (fs.existsSync(destination)) {
138	                    // Path-traversal guard: ensure the clone destination stays under projectsFolder.
139	                    const resolvedDest = path.resolve(destination);
140	                    if (!resolvedDest.startsWith(resolvedProjectsFolder + path.sep)) {
141	                        throw new Error(
142	                            `Security check failed: clone path "${resolvedDest}" is not under ` +
143	                            `projectsFolder "${resolvedProjectsFolder}"`
144	                        );
145	                    }
146	                    fs.rmSync(destination, { recursive: true, force: true });
147	                }
148	
149	                const credentials = this.config.gitCredentials ?? [];
150	                const credential = resolveCredential(repo.Url, credentials, repo.CredentialId);
151	                const host = extractHost(repo.Url);
152	
153	                // When no credential resolves for an HTTPS URL, report a descriptive
154	                // error rather than attempting an unauthenticated clone that would
155	                // likely fail with an unhelpful git error message.
156	                if (credential === null && host !== null) {
157	                    const errorMessage =
158	                        `Repository '${repo.Name}' requires a credential for host '${host}'. ` +
159	                        `Please select a credential in the repository settings.`;
160	                    this.errorLogManager?.append({
161	                        Severity: 'error',
162	                        Source: 'credentials',
163	                        Operation: 'workspace-setup',
164	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repoId },
165	                        Message: errorMessage,
166	                    });
167	                    return {
168	                        repositoryId: repoId,
169	                        success: false,
170	                        error: errorMessage,
171	                    };
172	                }
173	
174	                const cloneUrl = credential !== null
175	                    ? injectCredentialToken(repo.Url, credential.token)
176	                    : repo.Url;
177	
178	                const gitResult = await cloneRepository(cloneUrl, destination, {
179	                    depth: this.config.cloneDepth > 0 ? this.config.cloneDepth : undefined,
180	                    timeoutMs: CLONE_TIMEOUT_MS,
181	                });
182	
183	                if (gitResult.exitCode !== 0) {
184	                    const errorMessage = stripEmbeddedCredentials(gitResult.stderr) || `git clone exited with code ${gitResult.exitCode}`;
185	                    this.errorLogManager?.append({
186	                        Severity: 'error',
187	                        Source: 'clone',
188	                        Operation: 'workspace-setup',
189	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repoId },
190	                        Message: errorMessage,
191	                    });
192	                    return {
193	                        repositoryId: repoId,
194	                        success: false,
195	                        error: errorMessage,
196	                    };
197	                }
198	
199	                // Write a credential success entry so that checkWorkspaceHealth()
200	                // can suppress stale credential-missing badges for this repository.
201	                if (credential !== null) {
202	                    this.errorLogManager?.append({
203	                        Severity: 'info',
204	                        Source: 'credentials',
205	                        Operation: 'workspace-setup',
206	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repoId },
207	                        Message: `Repository '${repo.Name}' cloned successfully using credential '${credential.label}'.`,
208	                    });
209	                }
210	
211	                return { repositoryId: repoId, success: true };
212	            }),
213	        );
214	
215	        const repoPaths = project.Repositories.map((repoId) => ({
216	            slug: repoId,
217	            path: this.repoPath(projectId, workspaceId, repoId),
218	        }));
219	
220	        generateWorkspaceFile(
221	            workspaceId,
222	            repoPaths,
223	            this.wsFilePath(projectId, workspaceId),
224	        );
225	
226	        return { results: repoResults };
227	    }
228	
229	    /**
230	     * Deletes a workspace: removes the workspace folder on disk, the VS Code
231	     * .code-workspace file, and the workspace data entry.
232	     *
233	     * The workspace folder is silently skipped if it does not exist on disk.
234	     *
235	     * @throws {Error} If attempting to delete the STABLE workspace.
236	     * @throws {Error} If the computed workspace path is not under `projectsFolder`
237	     *   (path-traversal guard).
238	     * @throws {Error} If the project does not exist.
239	     * @throws {Error} If the workspace data entry does not exist.
240	     */
241	    deleteWorkspace(projectId: string, workspaceId: string): void {
242	        if (workspaceId === STABLE_WORKSPACE_ID) {
243	            throw new Error(
244	                `Cannot delete the STABLE workspace: it is the default workspace for ` +
245	                `project "${projectId}" and cannot be deleted.`
246	            );
247	        }
248	
249	        const wsFolder = this.workspaceFolder(projectId, workspaceId);
250	        const resolvedWsFolder = path.resolve(wsFolder);

101	     *   clone (`credential !== null`), a `Source: 'credentials'`, `Severity: 'info'`
102	     *   log entry is written. This allows `checkWorkspaceHealth()` to suppress
103	     *   stale `credential-missing` badges by inspecting the most recent entry per
104	     *   repository.
105	     */
106	    async addRepositoryToProject(
107	        projectId: string,
108	        repositoryId: string,
109	    ): Promise<AddRepositoryResult> {
110	        const repo = this.repositoryManager.getById(repositoryId);
111	        if (!repo) {
112	            throw new Error(
113	                `Cannot add repository: repository with ID "${repositoryId}" does not exist.`
114	            );
115	        }
116	
117	        // Update project data (also validates project existence and no duplicate repo).
118	        this.projectManager.addRepository(projectId, repositoryId);
119	
120	        // Re-read project to get the confirmed, updated workspace list.
121	        const project = this.projectManager.getById(projectId)!;
122	
123	        const resolvedProjectsFolder = path.resolve(this.config.projectsFolder);
124	
125	        const workspaceResults: WorkspaceCloneResult[] = await Promise.all(
126	            Object.keys(project.Workspaces).map(async (workspaceId): Promise<WorkspaceCloneResult> => {
127	                const destination = this.repoPath(projectId, workspaceId, repositoryId);
128	
129	                // Path-traversal guard: ensure the clone destination stays under projectsFolder.
130	                const resolvedDest = path.resolve(destination);
131	                if (!resolvedDest.startsWith(resolvedProjectsFolder + path.sep)) {
132	                    throw new Error(
133	                        `Security check failed: clone path "${resolvedDest}" is not under ` +
134	                        `projectsFolder "${resolvedProjectsFolder}"`
135	                    );
136	                }
137	
138	                const credentials = this.config.gitCredentials ?? [];
139	                const credential = resolveCredential(repo.Url, credentials, repo.CredentialId);
140	                const host = extractHost(repo.Url);
141	
142	                // When no credential resolves for an HTTPS URL, report a descriptive
143	                // error rather than attempting an unauthenticated clone that would
144	                // likely fail with an unhelpful git error message.
145	                if (credential === null && host !== null) {
146	                    const errorMessage =
147	                        `Repository '${repo.Name}' requires a credential for host '${host}'. ` +
148	                        `Please select a credential in the repository settings.`;
149	                    this.errorLogManager?.append({
150	                        Severity: 'error',
151	                        Source: 'credentials',
152	                        Operation: 'add-repository',
153	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repositoryId },
154	                        Message: errorMessage,
155	                    });
156	                    return {
157	                        workspaceId,
158	                        success: false,
159	                        error: errorMessage,
160	                    };
161	                }
162	
163	                const cloneUrl = credential !== null
164	                    ? injectCredentialToken(repo.Url, credential.token)
165	                    : repo.Url;
166	
167	                const gitResult = await cloneRepository(cloneUrl, destination, {
168	                    depth: this.config.cloneDepth > 0 ? this.config.cloneDepth : undefined,
169	                    timeoutMs: CLONE_TIMEOUT_MS,
170	                });
171	
172	                if (gitResult.exitCode !== 0) {
173	                    const errorMessage = stripEmbeddedCredentials(gitResult.stderr) || `git clone exited with code ${gitResult.exitCode}`;
174	                    this.errorLogManager?.append({
175	                        Severity: 'error',
176	                        Source: 'clone',
177	                        Operation: 'add-repository',
178	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repositoryId },
179	                        Message: errorMessage,
180	                    });
181	                    return {
182	                        workspaceId,
183	                        success: false,
184	                        error: errorMessage,
185	                    };
186	                }
187	
188	                // Write a credential success entry so that checkWorkspaceHealth()
189	                // can suppress stale credential-missing badges for this repository.
190	                if (credential !== null) {
191	                    this.errorLogManager?.append({
192	                        Severity: 'info',
193	                        Source: 'credentials',
194	                        Operation: 'add-repository',
195	                        Context: { ProjectId: projectId, WorkspaceId: workspaceId, RepositoryId: repositoryId },
196	                        Message: `Repository '${repo.Name}' cloned successfully using credential '${credential.label}'.`,
197	                    });
198	                }
199	
200	                return { workspaceId, success: true };
201	            }),
202	        );
203	
204	        // Regenerate all VS Code workspace files to include the new repository.
205	        for (const workspaceId of Object.keys(project.Workspaces)) {
206	            this.regenerateWorkspaceFile(projectId, workspaceId, project.Repositories);
207	        }
208	
209	        return { workspaceResults };
210	    }
211	
212	    /**
213	     * Removes a repository from a project: deletes clone folders from all
214	     * workspace folders, updates the project data, and regenerates all VS Code
215	     * workspace files.
216	     *
217	     * Clone folder deletions are skipped silently when the folder does not exist.
218	     * Each clone path is validated to be under `projectsFolder` before deletion.
219	     *
220	     * @throws {Error} If the project does not exist.
221	     * @throws {Error} If the repository is not listed in the project.
222	     */
223	    removeRepositoryFromProject(projectId: string, repositoryId: string): void {
224	        const project = this.projectManager.getById(projectId);
225	        if (!project) {
226	            throw new Error(
227	                `Cannot remove repository: project with ID "${projectId}" does not exist.`
228	            );
229	        }
230	
231	        const resolvedProjectsFolder = path.resolve(this.config.projectsFolder);
232	
233	        // Delete clone folders from all workspaces.
234	        for (const workspaceId of Object.keys(project.Workspaces)) {
235	            const clonePath = this.repoPath(projectId, workspaceId, repositoryId);
236	            const resolvedClonePath = path.resolve(clonePath);
237	
238	            // Path-traversal guard.
239	            if (!resolvedClonePath.startsWith(resolvedProjectsFolder + path.sep)) {
240	                throw new Error(
241	                    `Security check failed: clone path "${resolvedClonePath}" is not under ` +
242	                    `projectsFolder "${resolvedProjectsFolder}".`
243	                );
244	            }
245	
246	            if (fs.existsSync(clonePath)) {
247	                fs.rmSync(clonePath, { recursive: true, force: true });
248	            }
249	        }

101	    // de-duplication naturally keeps only the most recent entry per repository.
102	    if (errorLogManager) {
103	        const { entries } = errorLogManager.list({ source: 'credentials' });
104	
105	        // Filter to entries scoped to this workspace.
106	        const wsEntries = entries.filter(
107	            (e) =>
108	                e.Context.WorkspaceId === workspaceId &&
109	                e.Context.ProjectId === projectId &&
110	                e.Context.RepositoryId !== undefined,
111	        );
112	
113	        // De-duplicate by repository ID, keeping only the most recent entry per repo
114	        // (entries are returned newest-first from errorLogManager.list()).
115	        // Only push a credential-missing issue when the most recent entry is an error.
116	        const seenRepos = new Set<string>();
117	        for (const entry of wsEntries) {
118	            const repoId = entry.Context.RepositoryId!;
119	            if (!seenRepos.has(repoId)) {
120	                seenRepos.add(repoId);
121	                if (entry.Severity === 'error') {
122	                    issues.push({
123	                        type: 'credential-missing',
124	                        severity: 'warning',
125	                        message: entry.Message,
126	                        fixAction: 'configure-credential',
127	                        repositoryId: repoId,
128	                    });
129	                }
130	                // Severity: 'info' means the most recent credential operation
131	                // succeeded — suppress any stale credential-missing badge.
132	            }
133	        }
134	    }
135	
136	    return {
137	        healthy: issues.length === 0,
138	        issues,
139	    };
140	}

